const text = $json.output || "";

const scenes = text
  .split(/SCENE\s+\d+\s*:/i)
  .map(s => s.trim())
  .filter(Boolean)
  .map((scene, index) => ({
    scene_number: index + 1,
    visual_prompt: scene
  }));

return scenes.map(scene => ({ json: scene }));

const raw = $input.item.json.output;
const cleaned = raw.replace(/```json|```/g, '').trim();
const parsed = JSON.parse(cleaned);
return { json: parsed };
